function StudyPlanItemRow({ item, nodeId, document, disabled, busy, run, depth = 0 }: {
  item: UiStudyPlanItem;
  nodeId: string;
  document: UiDocument;
  disabled: boolean;
  busy: string | null;
  run: (action: UiAction, learnerTurn?: boolean) => Promise<boolean>;
  depth?: number;
}) {
