function mapElement(element: ElementNode, index: number): UiDocumentNode[] {
	const id = elementId(element, `openui-node-${index + 1}`);
	const props = element.props;
	switch (element.typeName) {
		case "Explanation": {
			const title = optionalText(props.title);
			return [{ type: "markdown", id, markdown: `${title ? `### ${title}\n\n` : ""}${text(props.markdown)}` }];
		}
		case "Callout": return [{ type: "callout", id, markdown: text(props.markdown), tone: text(props.tone, "info") as "info" | "hint" | "check" | "warning", ...(optionalText(props.title) ? { title: text(props.title) } : {}) }];
		case "Question": return [{
			type: "question-group",
			id,
			...(optionalText(props.topic) !== undefined ? { topic: text(props.topic) } : {}),
			...(optionalText(props.intro) !== undefined ? { intro: text(props.intro) } : {}),
			questions: Array.isArray(props.questions)
				? props.questions.map((entry, questionIndex) => question(id, entry, questionIndex))
				: [],
		}];
		case "Quiz": return [{ type: "quiz", id: contractId(text(props.id, id), id), title: text(props.topic, "Quiz"), questions: Array.isArray(props.questions) ? props.questions.map((entry, questionIndex) => question(id, entry, questionIndex, true)) : [] }];
		case "Flashcards": return [{
			type: "deck", id: contractId(text(props.id, id), id), title: text(props.title, "Flashcards"), topic: text(props.topic, "Study"),
			...(optionalText(props.description) !== undefined ? { description: text(props.description) } : {}),
			cards: Array.isArray(props.cards) ? props.cards.map((entry, cardIndex): UiDeckCard => {
				const card = record(entry);
				return { id: contractId(text(card.id, childId(id, "card", cardIndex)), childId(id, "card", cardIndex)), front: text(card.front, "Front"), back: text(card.back, "Back"), ...(textArray(card.tags) ? { tags: textArray(card.tags) } : {}) };
			}) : [],
		}];
		case "StudyPlan": return [{
			type: "study-plan", id: contractId(text(props.id, id), id), title: text(props.title, "Study plan"),
			...(optionalText(props.overview) ? { overview: text(props.overview) } : {}),
			items: Array.isArray(props.items) ? props.items.map((entry, itemIndex) => planItem(entry, itemIndex, id)) : [],
			...(Array.isArray(props.relatedPlans) ? { relatedPlans: props.relatedPlans.map(planLink) } : {}),
		}];
		case "ConceptMap": return [{ type: "concept-map", id, source: text(props.code), ...(optionalText(props.title) ? { title: text(props.title) } : {}) }];
		case "LearningImage": return [{ type: "image", id, alt: text(props.alt, "Learning image"), resource: { id: childId(id, "resource"), title: text(props.title, "Learning image"), format: "uri", uri: text(props.src) } }];
		case "LearningAnimation": return [{ type: "handoff", id, target: "web", reason: text(props.summary, `Open the ${text(props.topic, "learning")} animation in Keating web`), context: "The source interaction contains executable HTML, so the portable learner contract records an explicit trusted-surface handoff instead of embedding or executing it." }];
		case "SharedNotes": return [{ type: "notes", id: contractId(text(props.id, id), id), title: text(props.title, "Learner notes"), value: text(props.initialValue), ...(optionalText(props.placeholder) ? { placeholder: text(props.placeholder) } : {}) }];
		default: throw new Error(`OpenUI component ${element.typeName} has no shared semantic mapping.`);
	}
}

/** Compile the browser OpenUI language into the versioned cross-surface contract. */
export function compileOpenUISourceToSharedDocument(source: string, options: CompileSharedOpenUIOptions): UiDocument {
	const result = parser.parse(source);
	if (!result.root || result.root.typeName !== "LearningSurface") throw new Error("OpenUI source has no LearningSurface root.");
	if (result.meta.incomplete || result.root.partial) throw new Error("OpenUI source is incomplete.");
	if (result.meta.errors.length || result.meta.unresolved.length) throw new Error("OpenUI source contains invalid or unresolved components.");
	const content = result.root.props.content;
	if (!Array.isArray(content) || !content.every((entry) => record(entry).type === "element")) throw new Error("OpenUI LearningSurface content is invalid.");
	const at = options.updatedAt ?? options.createdAt ?? new Date().toISOString();
	const document: UiDocument = {
		schemaVersion: UI_CONTRACT_VERSION,
		id: contractId(options.documentId, "openui-document"),
		revision: options.revision ?? 0,
		lifecycle: "ready",
		retention: options.retention ?? retentionValue(result.root.props.lifecycle) ?? "resumable",
		supportedSurfaces: ["web", "desktop", "mobile", "terminal"],
		...(optionalText(result.root.props.title) ? { title: text(result.root.props.title) } : {}),
		...(optionalText(result.root.props.description) ? { description: text(result.root.props.description) } : {}),
		nodes: content.flatMap((entry, index) => mapElement(entry as ElementNode, index)),
		createdAt: options.createdAt ?? at,
		updatedAt: at,
	};
	if (!validateUiDocument(document)) throw new Error("Compiled OpenUI document does not satisfy the shared learner contract.");
	return document;
}
import type {
	OpenUIDocumentMetadata,
	OpenUIDocumentScope,
	OpenUIInteractionLifecycle,
	OpenUIMessageSegment,
} from "./types";
import { validateUiDocument, type UiDocument } from "@keating/learner-contracts";

const OPENUI_FENCE = /```openui(?:-lang)?(?:[ \t]+([^\n]*))?\n/g;
const DOCUMENT_ID = /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}$/;

function hashProgram(program: string): string {
	let hash = 2166136261;
	for (let index = 0; index < program.length; index += 1) {
		hash ^= program.charCodeAt(index);
		hash = Math.imul(hash, 16777619);
	}
	return (hash >>> 0).toString(36);
}

function parseLifecycle(value: string | undefined): OpenUIInteractionLifecycle {
	if (value === "resumable" || value === "workspace") return value;
	return "ephemeral";
}

function parseRevision(value: string | undefined): number {
	if (value === undefined) return 0;
	if (!/^\d+$/.test(value)) return 0;
	const revision = Number(value);
	return Number.isSafeInteger(revision) ? revision : 0;
}

function parseMetadata(
	header: string | undefined,
	program: string,
	sourceIndex = 0,
	documentScope: string | OpenUIDocumentScope = "",
): OpenUIDocumentMetadata {
	const entries = new Map<string, string>();
	for (const token of header?.trim().split(/\s+/) ?? []) {
		const separator = token.indexOf("=");
		if (separator <= 0) continue;
		entries.set(token.slice(0, separator), token.slice(separator + 1));
	}
	const candidateId = entries.get("id");
	const declaredId = candidateId && DOCUMENT_ID.test(candidateId) ? candidateId : undefined;
	const scope = typeof documentScope === "string"
		? documentScope
		: `${documentScope.sessionId}:${documentScope.messageId}`;
	const legacyScopes = typeof documentScope === "string" ? [] : [documentScope.messageId];
	const scopedDeclaredId = declaredId && scope
		? `openui-${hashProgram(`${scope}:${sourceIndex}`)}-${declaredId}`.slice(0, 128)
		: declaredId;
	const legacyIds = declaredId
		? legacyScopes.flatMap((legacyScope) => [
			`openui-${hashProgram(`${legacyScope}:${sourceIndex}`)}-${declaredId}`.slice(0, 128),
			`openui-${hashProgram(legacyScope)}-${declaredId}`.slice(0, 128),
		])
		: legacyScopes.map((legacyScope) => `openui-${hashProgram(`${legacyScope}:${header ?? ""}:${sourceIndex}`)}`);
	const id = scopedDeclaredId
		? scopedDeclaredId
		: `openui-${hashProgram(scope
			? `${scope}:${header ?? ""}:${sourceIndex}`
			: `${header ?? ""}:${sourceIndex}:${program}`)}`;
	return {
		id,
		lifecycle: parseLifecycle(entries.get("lifecycle")),
		revision: parseRevision(entries.get("revision")),
		...(typeof documentScope === "string" ? {} : { sessionId: documentScope.sessionId }),
		...(legacyIds.length > 0 ? { legacyIds: [...new Set(legacyIds)].filter((legacyId) => legacyId !== id) } : {}),
	};
}

function skipString(text: string, start: number): number {
	if (text[start] !== '"') return start;
	let index = start + 1;
	while (index < text.length) {
		if (text[index] === "\\") index += 2;
		else if (text[index] === '"') return index + 1;
		else index += 1;
	}
	return index;
}

function findClosingFence(text: string, bodyStart: number): { index: number; end: number } | null {
	let index = bodyStart;
	while (index < text.length) {
		const afterString = skipString(text, index);
		if (afterString > index) {
			index = afterString;
			continue;
		}

		const atLineStart = index === bodyStart || text[index - 1] === "\n";
		if (atLineStart && text.startsWith("```", index)) {
			const afterFence = index + 3;
			if (afterFence === text.length || text[afterFence] === "\n") {
				return {
					index: index === bodyStart ? index : index - 1,
					end: afterFence < text.length ? afterFence + 1 : afterFence,
				};
			}
		}
		index += 1;
	}
	return null;
}

/**
 * Return only top-level statements terminated by a newline. The OpenUI parser
 * intentionally auto-closes unfinished input, so passing it a partial
 * Question can mount a control before its choices or answer field exist.
 */
export function committedOpenUIProgram(program: string, fenceComplete = false): string {
	if (fenceComplete) return program.trimEnd();

	const stack: string[] = [];
	let inString = false;
	let escaped = false;
	let lastCommit = 0;

	for (let index = 0; index < program.length; index += 1) {
		const character = program[index];
		if (inString) {
			if (escaped) escaped = false;
			else if (character === "\\") escaped = true;
			else if (character === '"') inString = false;
			continue;
		}

		if (character === '"') {
			inString = true;
			continue;
		}
		if (character === "(" || character === "[" || character === "{") {
			stack.push(character);
			continue;
		}
		if (character === ")" || character === "]" || character === "}") {
			const expected = character === ")" ? "(" : character === "]" ? "[" : "{";
			if (stack.at(-1) !== expected) return program.slice(0, lastCommit).trimEnd();
			stack.pop();
			continue;
		}
		if (character === "\n" && stack.length === 0) lastCommit = index + 1;
	}

	return program.slice(0, lastCommit).trimEnd();
}

/**
 * Split assistant text into Markdown and OpenUI programs.
 *
 * An opening fence produces a segment immediately, but only whole top-level
 * statements are committed to the renderer. Existing Markdown and legacy
 * `<keating-*>` tags remain untouched in text segments.
 */
export function parseOpenUIMessageSegments(text: string, documentScope: string | OpenUIDocumentScope = ""): OpenUIMessageSegment[] {
	const segments: OpenUIMessageSegment[] = [];
	let cursor = 0;
	OPENUI_FENCE.lastIndex = 0;
	let match: RegExpExecArray | null;

	while ((match = OPENUI_FENCE.exec(text)) !== null) {
		if (match.index > cursor) {
			segments.push({ type: "text", content: text.slice(cursor, match.index) });
		}

		const bodyStart = OPENUI_FENCE.lastIndex;
		const closing = findClosingFence(text, bodyStart);
		const bodyEnd = closing?.index ?? text.length;
		const rawProgram = text.slice(bodyStart, bodyEnd);
		const metadata = parseMetadata(match[1], rawProgram, match.index, documentScope);
		const trimmed = rawProgram.trim();
		if (trimmed.startsWith("{")) {
			let document: UiDocument | undefined;
			let error: string | undefined;
			if (closing) {
				try {
					const candidate: unknown = JSON.parse(trimmed);
					if (!validateUiDocument(candidate)) throw new Error("The OpenUI JSON document does not satisfy the learner contract.");
					const scoped = { ...candidate, id: metadata.id, revision: metadata.revision };
					if (!validateUiDocument(scoped)) throw new Error("The scoped OpenUI JSON document does not satisfy the learner contract.");
					document = scoped;
				} catch (cause) {
					error = cause instanceof Error ? cause.message : "The OpenUI JSON document is invalid.";
				}
			}
			segments.push({ type: "openui", format: "document", program: "", rawProgram, complete: closing !== null, ...(document ? { document } : {}), ...(error ? { error } : {}), metadata });
		} else {
			segments.push({
				type: "openui",
				format: "source",
				program: committedOpenUIProgram(rawProgram, closing !== null),
				rawProgram,
				complete: closing !== null,
				metadata,
			});
		}

		if (!closing) {
			cursor = text.length;
			break;
		}
		cursor = closing.end;
		OPENUI_FENCE.lastIndex = cursor;
	}

	if (cursor < text.length) segments.push({ type: "text", content: text.slice(cursor) });
	if (segments.length === 0) segments.push({ type: "text", content: text });
	return segments;
}

/** Remove OpenUI source from text copied from an assistant message. */
export function stripOpenUIPrograms(text: string): string {
	return parseOpenUIMessageSegments(text)
		.filter((segment): segment is Extract<OpenUIMessageSegment, { type: "text" }> => segment.type === "text")
		.map((segment) => segment.content)
		.join("")
		.trim();
}

