	type: z.enum(["multiple_choice", "short_answer", "true_false", "fill_in", "transfer", "slider", "dropdown", "multi_select"]),
	level: z.enum(["recall", "comprehension", "application", "analysis", "transfer"]),
	question: z.string(),
	options: z.array(z.string()).optional(),
